315	static auto get_next_update_time(std::chrono::seconds update_period)
316	{
317	    using namespace std::chrono;
318	
319	    const auto now = time_point_cast<seconds>(system_clock::now());
320	
321	    // Use seconds since the start of the hour, because we don't know when
322	    // the epoch started, maybe on some weird fractional time.
323	    const auto start_of_hour = time_point_cast<seconds>(time_point_cast<hours>(now));
324	    const auto seconds_passed = now - start_of_hour;
325	
326	    // Rotate time forward by half a period -- e.g. if a period is a minute,
327	    // we'll collect metrics on start of minute + 30 seconds. This is to
328	    // achieve temporal separation with MetricTransmitter. Don't forget to
329	    // rotate it back.
330	    const auto rotation = update_period / 2;
331	
332	    const auto periods_passed = (seconds_passed + rotation) / update_period;
333	    const auto seconds_next = (periods_passed + 1) * update_period - rotation;
334	    const auto time_next = start_of_hour + seconds_next;
335	
336	    return time_next;
337	}
