339	void AsynchronousMetrics::run()
340	{
341	    setThreadName("AsyncMetrics");
342	
343	    while (true)
344	    {
345	        auto next_update_time = get_next_update_time(update_period);
346	
347	        {
348	            // Wait first, so that the first metric collection is also on even time.
349	            std::unique_lock lock{mutex};
350	            if (wait_cond.wait_until(lock, next_update_time,
351	                [this] { return quit; }))
352	            {
353	                break;
354	            }
355	        }
356	
357	        try
358	        {
359	            update(next_update_time);
360	        }
361	        catch (...)
362	        {
363	            tryLogCurrentException(__PRETTY_FUNCTION__);
364	        }
365	    }
366	}
