43	    const Poco::Util::AbstractConfiguration & config, const std::string & config_name,
44	    const AsynchronousMetrics & async_metrics_)
45	    : async_metrics(async_metrics_)
46	    , send_events(config.getBool(config_name + ".events", true))
47	    , send_metrics(config.getBool(config_name + ".metrics", true))
48	    , send_asynchronous_metrics(config.getBool(config_name + ".asynchronous_metrics", true))
49	    , send_status_info(config.getBool(config_name + ".status_info", true))
50	{
